def __init__(self, frac, default_len=10, charset=UTF, colour=None):
    if not (0 <= frac <= 1):
        warn("clamping frac to range [0, 1]", TqdmWarning, stacklevel=2)
        frac = max(0, min(1, frac))
    assert default_len > 0
    self.frac = frac
    self.default_len = default_len
    self.charset = charset
    self.colour = colour

@colour.setter
def colour(self, value):
    if not value:
        self._colour = None
        return
    try:
        if len(value) == 3:
            self._colour = self.COLOUR_RGB % value
        elif value.upper() in self.COLOURS:
            self._colour = self.COLOURS[value.upper()]
        else:
            raise KeyError
    except (KeyError, AttributeError):
        warn(("Unknown colour (%s); valid choices:"
              " [(0-255, 0-255, 0-255), %s]") % (
                  value, ", ".join(self.COLOURS)),
             TqdmWarning, stacklevel=2)
        self._colour = None

def __format__(self, format_spec):
    if format_spec:
        _type = format_spec[-1].lower()
        try:
            charset = dict(a=self.ASCII, u=self.UTF, b=self.BLANK)[_type]
        except KeyError:
            charset = self.charset
        else:
            format_spec = format_spec[:-1]
        if format_spec:
            N_BARS = int(format_spec)
            if N_BARS < 0:
                N_BARS += self.default_len
        else:
            N_BARS = self.default_len
    else:
        charset = self.charset
        N_BARS = self.default_len

    nsyms = len(charset) - 1
    bar_length, frac_bar_length = divmod(
        int(self.frac * N_BARS * nsyms), nsyms)

    bar = charset[-1] * bar_length
    frac_bar = charset[frac_bar_length]

    # whitespace padding
    if bar_length < N_BARS:
        bar = bar + frac_bar + \
            charset[0] * (N_BARS - bar_length - 1)
    if self.colour:
        return self.colour + bar + self.COLOUR_RESET
    return bar

